import{_ as p,o as e,c as t,a1 as r}from"./chunks/framework.DhXu_kq-.js";const _=JSON.parse('{"title":"第一章 雨，梦和我","description":"","frontmatter":{},"headers":[],"relativePath":"fan-made/articles/rainy_memory_and_fable.md","filePath":"fan-made/articles/rainy_memory_and_fable.md"}'),o={name:"fan-made/articles/rainy_memory_and_fable.md"};function n(i,a,l,m,s,c){return e(),t("div",null,a[0]||(a[0]=[r('<blockquote><p>文章作者: omca</p></blockquote><hr><h1 id="第一章-雨-梦和我" tabindex="-1">第一章 雨，梦和我 <a class="header-anchor" href="#第一章-雨-梦和我" aria-label="Permalink to &quot;第一章 雨，梦和我&quot;">​</a></h1><p>“这里。。真美”露薇娅感叹到，她无忧无虑地走在废墟上，即使这里被雨淋过不知道多久，早就没了以前的繁荣相貌。“那个。。”露薇娅浅浅地问了一句，“我该叫你什么好呢？”</p><p>他没有应答，只是默默看向远方，雨依旧下着，貌似逐渐变大了，在露薇娅问了第二遍后，他刚准备回答，但。。此刻他的头突然剧烈疼痛起来，不知为何，他想起来一些以往的记忆</p><p>“你怎么了？”露薇娅耐心地问他。</p><p>“没事，只是。。”话还没说完，他就晕倒了。此刻露薇娅也惊呆了，心里默想着：“为什么他会晕倒呢？明明也不受雨的影响”露薇娅将他送到一栋空房里，那里原本只是一个咖啡厅。露薇娅将他带到咖啡厅之后，她立即检查了他的脉搏“奇怪了，为什么脉搏还在运作呢？”她的不解贯彻在脑海里</p><p>这时候，有个人走了进来，露薇娅回头一看，那是一个女孩，她的头发是棕黄的，带着一副很小的眼镜，她看到露薇娅后，十分惊讶：“好久没看到了。。”露薇娅问到：“你是谁？为什么会在这里？”紧接着又补充一句：“难道你也是。。”“不会，不会，我们也是被那群人所逼到这里的”那位少女摇了摇手，可露薇娅依旧很警惕地看着她。</p><p>“别紧张，我们跟你们一样，也是被驱逐出来的”那位少女轻轻开口道，露薇娅虽然半信半疑，但眼下别无选择，她问到：“你为什么会在这里？”那位少女并没有说，或者说，她避开了这个问题：“这个问题我们以后再说，先说下我的名字吧，我的名字叫魏欣，地上那个人是你的同伴吧”露薇娅点了点头：“我们在路上的时候他突然晕倒了，于是我们就来到了这里”那位少女只是轻轻地回了一句“跟我来”</p><p>那是一个大房间，里面的东西有很多，相比高塔就丰富了许多，他们有许多食物，设备，和曾经这座城市的地图。里面还有5个人，其中有3位女的，2位男的“外面怎么样？”其中一位男生提了一嘴“哎。。还是没找到解决问题的方法”有个女生看到魏欣带着两个人来到了这里，就问：“这两人是谁？为什么会在这里？”魏欣说到：“他们跟我们一样，都是外面的流浪者，只不过有个人晕倒了，不知道为什么”她将他放到了一处空地，就问露薇娅：“你有什么能力吗？”露薇娅结结巴巴地说“我。。我可以。。看别人梦境，让他醒来”</p><p>此时这里鸦片无声。。</p><p>在高塔那边，人们已经发现他们俩逃走了，就大骂苏珊放走了他们，还说什么与恶魔勾结的人必将会死，即使苏珊解释了很多次都无济于事，最终被关进牢笼里了。对此，有些人问首领说：“首领，现在怎么办？我们到现在都还没找到他们”那首领不慌不忙地说：“不用着急，他们必定会联系那些人的”，说罢，便将墙上的壁纸撕下来了，又默默说了几句“那个机器人真的可以吗？”</p><p>镜头一转，他进入到了一个漆黑的空间，他不知道自己该干什么，旁边是一个小女孩，而那个小女孩她过了一会说：“爸爸？爸爸，你错了”他很恍惚，他不记得他有一个女儿，就问：“爸爸？是我？”</p><p>那小女孩点了点头，此时周围的数据开始乱码，时不时弹出来个花屏，而那个小女孩对他说：“坚持到底并不重要重要重要重要重要重要重要重要”随后被掐屏了。</p><p>此时一位黄色头发的小女孩在一个房间里偷偷上传数据，嘴里还念叨着：“这真的是你吗？”</p><p>遥想10年前她还是7岁的时候，某个人给了她一个很宝贵的礼物，而这时候他看到了电脑上的数据转移项目，就立即对她说：“你不要命了？！你知道这玩意有多危险吗？啊？我告诉。。”话还没说完，突然来了一大群人冲进他的家里，随后大喊：“不许动！不然我们就枪毙你们了！”此时那个小女孩刚拿起一把手枪，对方毫无收敛地对着她开枪，关键时候，他帮那个小女孩挡住了那几枪，随后小女孩和他倒在那边，那些人就冲上前去抓走了他</p><p>不久等到她醒来时，发现不仅他不见了，家里还少了个硬盘，而她知道这个硬盘里存着什么东西——数据人格</p><p>“10年了。。”她默默敲击着键盘，自从他消失之后，她就一直在寻找他的踪迹，当最后一个回车敲下时，一个简单的程序就完成了，她看了看，确定没有什么问题之后，随即便按下了启动键。</p><p>“爸爸。。”</p><p>“这是。。哪？”他看向那座桥，那座桥是由一串串紫色数据组成的，而他的对面，是他自己？“我这是。。死了吗？”他问到，心中的不解在心中燃烧，他突然想起了露薇娅：“对了，露薇娅不是可以进入别人梦境吗？怎么他还没进去？”</p><p>此时露薇娅也焦急万分，她傻了，之前明明可以进入苏珊的梦境，但却进不了他的梦境，她询问了一下有没有人帮她连一下他脑子，幸运的是，有个人愿意连接他的大脑，结果里面显示的是：“你无权进入，请杀死连接者”大家都蒙了，啥情况？人家做梦也没见过无权的啊？</p><p>此时某个首领默默的走进了一个秘密房间，那是连接顶层和地下的唯一通道，他走进去，里面有一个冬眠仓，里面还有一个人，情况似乎不太妙</p><p>而那个首领望着他：“嗯。。这就对了，希望一切顺利”</p>',23)]))}const f=p(o,[["render",n]]);export{_ as __pageData,f as default};
